WITH enriched AS (SELECT *, FIRST_VALUE(pressure, TRUE) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_pressure, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY temp_c, id) AS seq_no FROM device_readings) SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, seq_no FROM enriched ORDER BY humidity NULLS FIRST, id
